        theme.colours.charts[4] = $("[name=chartColour3]", container).val();
        theme.colours.charts[5] = $("[name=chartColour4]", container).val();
        
        await api.post("DMS/CRM/" + tenant.Id + "/Theme/Colours/colours.json", theme).then(() => {
