                },
            ]
        });
        //Gets the html files and inits the foldermanagement component
        var testimonialFiles = (await api.get("DocumentManagement/Folder?$filter=AppId eq " + app.Id + " and Path eq 'content/testimonials/html'&$expand=Files")).value[0];
        FolderManagement.init(app, $(".component[name=FolderManagement]", $("[name=testimonialsFolder]", container)), testimonialFiles, true, true);

        $("[name=addTestimonial]", container).off("click").on("click", async (e) => await TestimonialManagement.addTestimonial(e, container));
    },

addTestimonial: async function(e) {
    e.preventDefault();
    var newTestimonyDialog = new Dialog({ width: 600, height: "auto", title: "[resource_displayname[newtestimony]]" });
    newTestimonyDialog.template = $("[name=newTestimonyDialog]").html();
    newTestimonyDialog.events.create = async function (e) {
        e.preventDefault();
        var companyName = $("[name=companyName]").val();
        var contactName = $("[name=contactName]").val();
        var jobTitle = $("[name=jobTitle]").val();
        var content = $("[name=content]").val();
        var htmlContent = `<img src="[api[root]]DMS/content/testimonials/images/${companyName}logo.png" style="margin: 15px 0 -5px 0; max-height: 70px;"> <br>`;

        if (contactName) {
            htmlContent += `<p> ${contactName}</p>`;
        }

        if (jobTitle) {
            htmlContent += `<p> ${jobTitle}</p>`;
        }

        htmlContent += `<p style="padding-top: 15px; font-size: 14px; font-weight: normal;">"${content}"</p>`;

        await api.sendRaw("POST", "DMS/Content/Testimonials/html/" + companyName + "Testimonial.html", htmlContent, "text/plain").then(async () => {
            notification.success("[resource_displayname[testimonialsubmitted]]");
        }).catch((err) => error(err));
        newTestimonyDialog.events.close();
    };
    newTestimonyDialog.init(() => {
        TestimonialManagement.initCompanyLogoFileUpload(newTestimonyDialog.element);
    });
},


    initCompanyLogoFileUpload: async function (container) {
        var companyLogoDrop = new FileDropContainerWidget($("[name=companyLogo]", container));
        companyLogoDrop.events.drop = async (e) => {
            e.preventDefault();
            e.stopPropagation();
            var companyName = $("[name=companyName]", container).val();
            var files = e.target.files;
            if (files.length === 0) {
                files = e.originalEvent.dataTransfer.files;
            }
            if (files.length > 1) {
                error("[resource_displayname[onlyonefile]]");
                return;
            }
            var file = files[0];
            await api.file.upload("Content/Testimonials/Images/" + companyName + "Logo.png", file);
            $("[name=companyLogo]", container).attr("src", "[api[root]]/DMS/Content/Testimonials/Images/" + companyName + "Logo.png?time=" + (new Date()).toISOString());
        };
        companyLogoDrop.init();
    },

};",
